@Test
public void testELEscapingTomcatJuel() {
    assumeTrue(elAvailable);
    assumeThat(elImpl, anyOf(equalTo("tomcat"), equalTo("juel")));
    // not so much a test as an illustration that the specified EL implementations are seemingly confused by leading
    // backslashes and treats the whole expression as literal. We could skip any literal text before the first
    // non-escaped $, but that would only expose us to inconsistency for composite expressions containing more
    // than one component EL expression
    ApacheMessageContext context = context("12345678", () -> validator.getConstraintsForClass(Person.class).getConstraintsForProperty("idNumber").getConstraintDescriptors().stream().filter(forConstraintType(Pattern.class)).findFirst().orElseThrow(() -> new AssertionError("expected constraint missing")));
    when(context.getConfigurationProperty(ApacheValidatorConfiguration.Properties.CUSTOM_TEMPLATE_EXPRESSION_EVALUATION)).thenAnswer(invocation -> Boolean.toString(true));
    assertEquals("${regexp.charAt(4)}", interpolator.interpolate("\\${regexp.charAt(4)}", context));
    assertEquals("${regexp.charAt(4)}", interpolator.interpolate("\\\\${regexp.charAt(4)}", context));
}

@Test
public void testELEscapingRI() {
    assumeTrue(elAvailable);
    assumeThat(elImpl, equalTo("ri"));
    ApacheMessageContext context = context("12345678", () -> validator.getConstraintsForClass(Person.class).getConstraintsForProperty("idNumber").getConstraintDescriptors().stream().filter(forConstraintType(Pattern.class)).findFirst().orElseThrow(() -> new AssertionError("expected constraint missing")));
    when(context.getConfigurationProperty(ApacheValidatorConfiguration.Properties.CUSTOM_TEMPLATE_EXPRESSION_EVALUATION)).thenAnswer(invocation -> Boolean.toString(true));
    assertEquals("returns literal", "${regexp.charAt(4)}", interpolator.interpolate("\\${regexp.charAt(4)}", context));
    assertEquals("returns literal \\ followed by $, later interpreted as an escape sequence", "$", interpolator.interpolate("\\\\${regexp.charAt(4)}", context));
    assertEquals("returns literal \\ followed by .", "\\.", interpolator.interpolate("\\\\${regexp.charAt(3)}", context));
}

@Test
