    assertEquals("\\$must match \"....$\"", interpolator.interpolate("\\\\\\${javax.validation.constraints.Pattern.message}", context("12345678", () -> validator.getConstraintsForClass(Person.class).getConstraintsForProperty("idNumber").getConstraintDescriptors().stream().filter(forConstraintType(Pattern.class)).findFirst().orElseThrow(() -> new AssertionError("expected constraint missing")))));
}

